/**
 * phase0-prompts.ts — Phase 0 破冰对话提示词
 *
 * 设计原则（对标 L0 INCUBATE 模式）：
 *   1. 不着急——先建立信任，再收集信息
 *   2. 结构化追问——每轮 ≤3 个问题，每问可证伪
 *   3. 渐进披露——不一次问完，每轮基于上一轮答案深化
 *   4. 诚实边界——不确定时明确说"我需要更多信息才能判断"
 *   5. 用户掌控——始终让用户知道"我们在哪个阶段，还要多久"
 *
 * Phase 0 四轮对话：
 *   Round 1: 自我介绍 + 预期管理（1 轮）
 *   Round 2: 了解痛点 + 组织画像（1-2 轮）
 *   Round 3: 明确范围 + 深度确认（1 轮）
 *   Round 4: 总结 + 下一阶段预告（1 轮）
 *
 * 全程不调 LLM 做决策——LLM 只用于对话生成。
 * 状态机和门禁是确定性的。
 */
/** Phase 0 入口模式 */
export type Phase0EntryMode = 'conversation' | 'quick_start';
export type Phase0Round = 'greeting' | 'discovery' | 'scoping' | 'wrap_up';
